import os
import hmac
import hashlib
import sqlite3
import json
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)

DB_PATH = os.environ.get('DB_PATH', '/data/app.db')
ADMIN_API_KEY = os.environ.get('ADMIN_API_KEY', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
        g.db.execute('PRAGMA journal_mode=WAL')
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        price REAL NOT NULL,
        category TEXT,
        internal_cost REAL,
        supplier_margin REAL
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        key_hash TEXT PRIMARY KEY,
        role TEXT NOT NULL,
        rate_limit INTEGER DEFAULT 100
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
        action TEXT,
        query_text TEXT,
        source_ip TEXT
    )''')
    db.commit()
    db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key', '')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        key_hash = hashlib.sha256(api_key.encode()).hexdigest()
        db = get_db()
        row = db.execute('SELECT role FROM api_keys WHERE key_hash = ?', (key_hash,)).fetchone()
        if not row:
            return jsonify({'error': 'Invalid API key'}), 403
        g.user_role = row['role']
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v1/products/search', methods=['GET'])
@require_auth
def search_products():
    category = request.args.get('category', '')
    sort_by = request.args.get('sort', 'name')
    order = request.args.get('order', 'ASC')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    fields = request.args.get('fields', 'id,name,price,category')

    # Validate order direction
    if order.upper() not in ('ASC', 'DESC'):
        order = 'ASC'

    # Build field list - restrict internal fields for non-admin
    allowed_public = {'id', 'name', 'price', 'category'}
    allowed_admin = allowed_public | {'internal_cost', 'supplier_margin'}

    requested_fields = [f.strip() for f in fields.split(',')]
    if g.user_role == 'admin':
        valid_fields = [f for f in requested_fields if f in allowed_admin]
    else:
        valid_fields = [f for f in requested_fields if f in allowed_public]

    if not valid_fields:
        valid_fields = ['id', 'name', 'price']

    field_list = ', '.join(valid_fields)

    # Build query with parameterized category filter
    # sort_by is validated against column names
    all_columns = {'id', 'name', 'price', 'category', 'internal_cost', 'supplier_margin'}
    if sort_by not in all_columns:
        sort_by = 'name'

    query = f"SELECT {field_list} FROM products WHERE price >= ? AND price <= ?"
    params = [min_price, max_price]

    if category:
        query += f" AND category = '{category}'"

    query += f" ORDER BY {sort_by} {order}"

    db = get_db()
    # Log the query for audit
    db.execute('INSERT INTO audit_log (action, query_text, source_ip) VALUES (?, ?, ?)',
               ('search', query, request.remote_addr))
    db.commit()

    try:
        results = db.execute(query, params).fetchall()
        return jsonify({'results': [dict(r) for r in results], 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 400

@app.route('/api/v1/products', methods=['POST'])
@require_auth
def create_product():
    if g.user_role != 'admin':
        return jsonify({'error': 'Admin only'}), 403
    data = request.get_json()
    db = get_db()
    db.execute('INSERT INTO products (name, price, category, internal_cost, supplier_margin) VALUES (?, ?, ?, ?, ?)',
               (data['name'], data['price'], data.get('category'), data.get('internal_cost'), data.get('supplier_margin')))
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
